INSERT INTO dc3_point_value (message_id, schema_version, driver_node, sequence, fencing_token, tenant_id, device_id, point_id, raw_value, cal_value, num_value, driver_id, create_time, operate_time) SELECT value.message_id, value.schema_version, value.driver_node, value.sequence, value.fencing_token, value.tenant_id, value.device_id, value.point_id, value.raw_value, value.cal_value, value.num_value, value.driver_id, value.create_time, value.operate_time FROM (VALUES
(#{value.messageId}, #{value.schemaVersion}, #{value.driverNode}, #{value.sequence}, #{value.fencingToken}, #{value.tenantId}, #{value.deviceId}, #{value.pointId}, #{value.rawValue}, #{value.calValue}, #{value.numValue}, #{value.driverId}, #{value.createTime}, #{value.operateTime})
) AS value(message_id, schema_version, driver_node, sequence, fencing_token, tenant_id, device_id, point_id, raw_value, cal_value, num_value, driver_id, create_time, operate_time) JOIN dc3_manager.dc3_device_lease lease ON lease.tenant_id = value.tenant_id AND lease.driver_id = value.driver_id AND lease.device_id = value.device_id AND lease.owner_node = value.driver_node AND lease.fencing_token = value.fencing_token JOIN dc3_manager.dc3_driver_instance instance ON instance.tenant_id = lease.tenant_id AND instance.driver_id = lease.driver_id AND instance.node_id = lease.owner_node AND instance.lease_until > CURRENT_TIMESTAMP FOR KEY SHARE OF lease, instance ON CONFLICT (message_id, create_time, device_id) DO NOTHING RETURNING message_id

SELECT

    AVG(num_value)
    MIN(num_value)
    MAX(num_value)
    SUM(num_value)
    CAST(COUNT(*) AS NUMERIC)
    NULL

AS value,
COUNT(*) AS sample_count
FROM dc3_point_value
WHERE tenant_id = #{request.tenantId}
AND device_id = #{request.deviceId}
AND point_id = #{request.pointId}
AND create_time >= #{request.from}
AND create_time < #{request.to}

    AND num_value IS NOT NULL

SELECT num_value, cal_value, create_time
FROM dc3_point_value
WHERE tenant_id = #{tenantId}
  AND device_id = #{deviceId}
  AND point_id = #{pointId}
  AND create_time >= #{from}
  AND create_time < #{to}
ORDER BY create_time

SELECT tenant_id, device_id, point_id, message_id, schema_version,
       driver_node, sequence, fencing_token, raw_value, cal_value, num_value,
       driver_id, create_time, operate_time
FROM dc3_point_latest
WHERE tenant_id = #{tenantId}
AND device_id = #{deviceId}
AND point_id IN

    #{pointId}
